MultiLanguageSpellData['en'][1282455] = {name = "[q3]Evercore Dome Dinger", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (3), Evercore\nOptional Reagents:\nProfession Trainer:\nMidnight Engineering (20)\nCost:\n110\n\n[q3]Evercore Dome Dinger\nBinds when equipped\nRanged Gun\n83 - 154 Damage Speed 3.00\n(39.5 damage per second)\n+53 Agility\n+628 Stamina\n[q2]+ 80 Random Stat 1\nDurability 100 / 100\n90\n[q]\"For when you see a dome that needs dingin'.\""}
MultiLanguageSpellData['en'][1282456] = {name = "[q4]P.O.W. x3", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nMalleable Wireframe (6), Mote of Wild Magic (6), Mote of Primal Energy (6), Dazzling Thorium (3), Tormented Tantalum , Aetherlume (10), Evercore (4), Spark (#401) (4)\nOptional Reagents:\nSpecialization:\nCombat Analytics - Guns\n\n[q4]P.O.W. x3\nBinds when picked up\nRanged Gun\n83 - 154 Damage Speed 3.00\n(39.5 damage per second)\n+53 Agility\n+628 Stamina\n[q2]+ 89 Random Stat 1\n90\n[q]\"Come on, shoot even faster!\""}
MultiLanguageSpellData['en'][1282457] = {name = "[q2]Thalassian Competitor's Rifle", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nMalleable Wireframe (3), Soul Sprocket (4), Evercore (3), Competitor's Heraldry (#471) (10)\nOptional Reagents:\nVendor:\nMirvedon\nZone:\nSilvermoon City\nCost:\n7500\n\n[q2]Thalassian Competitor's Rifle\nBinds when equipped\nRanged Gun\n2,868 - 5,327 Damage Speed 3.00\n(1,366 damage per second)\n+1,815 Agility\n+35,301 Stamina\n[q2]+ 599 Random Stat 1\n[q2]+ 599 Random Stat 2\n80"}
