MultiLanguageSpellData['en'][1289744] = {name = "Concentrated Silvermoon Health Potion", additional_info = "2 sec cast\nReagents:\nCursebound Globe (2), Silvermoon Health Potion (25)\nOptional Reagents:\nVendor:\nJan'sari the Watchful\nZone:\nThe Coiled Isle\nCost:\n150\n\n\n[q2]Use: Restores 359499 health.\n81\n[q]\"Created by experienced alchemists. Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1289745] = {name = "Liquid Luster", additional_info = "2 sec cast\nReagents:\nNeutralized Venom Clot , Cursebound Globe , Tranquility Bloom (8), Sanguithorn (6), Sunglass Vial (5)\nOptional Reagents:\nVendor:\nSkull of Er'inye\nZone:\nVaults of Atal'Utek\nCost:\n2500\n150\n\n\n[q2]Use: Drink to apply Lustrous Gleam every 6 seconds for 30 sec seconds, increasing your Versatility by 358 while this potion is active.\n\nApplications of Lustrous Gleam stack up to 5 times.\n81\n[q]\"Created by experienced alchemists. Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1289746] = {name = "Alluring Nostrum", additional_info = "2 sec cast\nReagents:\nNeutralized Venom Clot , Cursebound Globe , Tranquility Bloom (8), Sanguithorn (3), Mana Lily (3), Sunglass Vial (5)\nOptional Reagents:\nVendor:\nSecond Mate Sluggs\nZone:\nThe Coiled Isle\nCost:\n150\n\n\n[q2]Use: Accept the Void's gifts, empowering your damaging spells and abilities a chance to deal 10724 Shadow damage to your current target and up to 4 nearby enemies for 30 sec.\n\nThe Void's boons will burden you, slowing your movement speed by 15%, stacking up to 5 times.\n81\n[q]\"Created by experienced alchemists. Can be bought and sold on the Auction House.\""}
