MultiLanguageSpellData['en'][1291683] = {name = "[q3]Hunter's Ritual Stone", additional_info = "2 sec cast\nTools: Blacksmith Hammer\nReagents:\nLuminant Flux (4), Neutralized Venom Clot (2), Cursebound Globe (2), Umbral Tin Ore (6), Refulgent Copper Ingot (3)\nOptional Reagents:\nVendor:\nConstruct V'anore\nZone:\nSilvermoon City\nCost:\n150\n500\n\n[q3]Hunter's Ritual Stone\nOptional Crafting Reagent\n[q2]+15 Recipe Difficulty\n[q2]Provides the following property: Your damaging spells and abilities have a chance to grant 101 of a random secondary stat for 15 sec.\n\n While on a Prey Hunt this effect is increased by 50%. This bonus is only available outdoors while hunting prey.\n[q]Usable with: Midnight Blacksmithing Weapons\n[q]\"Crafted by players with the Blacksmithing skill. Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1291687] = {name = "[q3]Coiled Snake-Eye", additional_info = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (10), Neutralized Venom Clot (3), Evercore (5)\nOptional Reagents:\nDrop:\nWorld Creatures\n\n[q3]Coiled Snake-Eye\nOptional Crafting Reagent\n[q2]+15 Recipe Difficulty\n[q2]Provides the following property:\n Your damaging spells and abilties have a chance to grant 67 of a random secondary stat for 15 sec.\n\n If this effect was triggered by a Critical Strike, it grants your highest secondary stat instead.\n[q]Usable with: Midnight Engineering Guns\n[q]\"Can be bought and sold on the Auction House.\""}
