MultiLanguageSpellData['en'][1291690] = {name = "[q3]Polished Ammolite", additional_info = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nNeutralized Venom Clot (6), Cursebound Globe (4), Sin'dorei Lens (2), Glimmering Gemdust (2)\nOptional Reagents:\nDrop:\nWorld Creatures\n\n[q3]Polished Ammolite\nOptional Crafting Reagent\n[q2]+15 Recipe Difficulty\n[q2]Provides the following property: Critical strikes bestow a stacking blessing that grants more Critical Strike. At maximum stacks, critical strikes cause a burst of damage.\n[q]Usable with: Midnight recipes for most unembellished accessories.\n[q]\"Can be bought and sold on the Auction House.\""}
MultiLanguageSpellData['en'][1291691] = {name = "[q3]Adorned Fang", additional_info = "2 sec cast\nReagents:\nNeutralized Venom Clot (6), Carving Canine , Peerless Plumage , Cursebound Globe (8), Void-Tempered Hide , Dusk-Shrouded Stone (2)\nOptional Reagents:\nDrop:\nThe Twin Fangs\nZone:\nThe Venomous Abyss\n\n[q3]Adorned Fang\n71\nOptional Crafting Reagent\n[q2]+15 Recipe Difficulty\n[q2]Provides the following property: Your spells and abilities have a chance to increase your Haste, with the chance increasing when a target is at lower health.\n[q]Usable with: Midnight recipes for most unembellished equipment.\n[q]\"Can be bought and sold on the Auction House.\""}
