MultiLanguageSpellData['en'][1301494] = {name = "Cursed Umbral Tin", additional_info = "5 yd range\n2.5 sec cast\n[q]Umbral Tin is distinguished from its less impressive cousin by the deep shade of the ore. It resembles the inky black sky. Umbral Tin is more durable yet also more flexible than most other metals.\n\nThis deposit writhes with Ula'tek's curse. Standing near it makes the air feel heavier, as if drenched in the rage of every soul sacrificed on the altar of hubris."}
MultiLanguageSpellData['en'][1301495] = {name = "Overload Cursed Deposits", additional_info = "5 yd range\n2.5 sec cast\n[q]Overloading a Cursed ore deposit draws out more of the curse within it. Experienced miners can hold this curse in their hands, willing it into solid form."}
