MultiLanguageSpellData['en'][1303467] = {name = "Lithic Plumage", additional_info = "Approximately 1 procs per minute\n[q]Taking damage has a chance to fortify you, reducing incoming damage by 75% up to a cap.\n\n The damage cap is increased for each nearby Poisoned enemy.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303468] = {name = "Ouroboric Cycle", additional_info = "Approximately 1 procs per minute\n[q]Chance during combat to begin an Ouroboric Cycle, increasing all Tertiaries for 5 sec, then all Secondaries for 5 sec, then your Primary Stat for 5 sec.\n\n In this state, slaying an enemy causes 1 additional Cycle to occur after the last.\n\n While you are Poisoned, each Cycle's duration is extended by 1 sec.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303469] = {name = "Gorgoneion Gaze", additional_info = "[q]Upon dropping below 50% health, petrify all enemies within 10 yards for 10 sec. Petrified targets are stunned and invulnerable.\n\n When they break free, enemies are Poisoned, taking Nature damage every 1 sec and slowed by 50% for 5 sec. (1 min Cooldown)"}
MultiLanguageSpellData['en'][1303470] = {name = "Mephitic Cloud", additional_info = "Approximately 1 procs per minute\n[q]Chance during combat to apply Mephitic Cloud to nearby party members and enemies for 10 sec.\n\n Afflicted allies' spells and abilities Poison their target, dealing Nature damage over 5 sec, while afflicted enemies' spells and abilities additionally heal their target.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303471] = {name = "Viperine Grasp", additional_info = "Approximately 1 procs per minute\n[q]Your harmful spells and abilities have a chance to pull up to 2 nearby enemies to your current target's location, dealing Nature damage to affected targets.\n\n Up to 3 nearby Poisoned enemies are also pulled in.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303472] = {name = "Ophidian Maw", additional_info = "Approximately 1 procs per minute\n[q]Damaging an enemy has a chance to call a giant snake that erupts from below, gnashing at the target's location and dealing Nature damage split between nearby enemies.\n\n Any Poisoned non-boss creature damaged below 20% health is executed.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303473] = {name = "Virulent Mucus", additional_info = "Approximately 1 procs per minute\n[q]Upon entering combat, veil yourself in 5 layers of Virulent Mucus, each stack negating an instance of incoming damage that would exceed 5% of your maximum health.\n\n Dealing damage to a Poisoned enemy has a very low chance to grant you 1 additional layer of Mucus.\n(1m cooldown)"}
MultiLanguageSpellData['en'][1303474] = {name = "Accursed Poison", additional_info = "Approximately 1 procs per minute\n[q]Chance during combat to inflict Accursed Poison on the strongest enemy, dealing Nature damage every 1 sec for 1 min.\n\n The next time the afflicted target would cast an interruptible spell or ability, the Accursed Poison triggers, interrupting it immediately before removing itself.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303475] = {name = "Plague of Corrosion", additional_info = "Approximately 1 procs per minute\n[q]Chance during combat to apply a stacking Poison to all nearby enemies, dealing Nature damage every 2 sec for 1 min.\n\n On death, the Poison and its remaining duration are transferred to a new target.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303476] = {name = "Miasma Geyser", additional_info = "Approximately 1 procs per minute\n[q]Chance during combat to stir up a Miasma Geyser under a nearby unit that erupts after 10 sec, dealing Nature damage split between enemy units while also healing all allies inside.\n\n Poisoned units take increased damage and healing.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303477] = {name = "Ula'tek's Gift", additional_info = "Approximately 2 procs per minute\n[q]Your harmful spells and abilities have a chance to afflict your target with 5 stacks of Ula'Tek's Gift, dealing Nature damage per application every 5 sec for 1 min.\n\n While you are Poisoned, apply 5 additional stacks.\n\n Upon applying 20 stacks to a target, the Gift Corrodes, dealing the remainder of its damage immediately before removing itself.\n(2s cooldown)"}
MultiLanguageSpellData['en'][1303478] = {name = "Insidious Venom", additional_info = "Approximately 1 procs per minute\n[q]Chance during combat to Poison yourself, lowering all of your Secondary and Tertiary Stats while greatly increasing your Primary Stat for 12 sec.\n(1s cooldown)"}
MultiLanguageSpellData['en'][1303479] = {name = "Sanguine Rancor", additional_info = "Instant\n[q]Your attacks have a very high chance to build sanguine rancor within you. After 15 times, the rancor erupts to scourge your target and all nearby enemies with crimson bile, dealing ( 25761 * 1 ) Shadow damage split between them. Damage increased by 30% per additional enemy, up to 150%.\n\n If only one enemy is struck, the concentrated bile deals an additional ( 25761 * 25 / 100 * 1 ) Shadow damage over 3 sec."}
