MultiLanguageSpellData['en'][1305204] = {name = "Crested Ember Leafmimic", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"This sturdy leafmimic can be found only in the warmest of areas. Its red scales allow it to hide undiscovered in the heated alcoves it prefers.\"\nTrading Post"}
MultiLanguageSpellData['en'][1305206] = {name = "Crested Aqua Leafmimic", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The aqua leafmimic is a rare sight indeed. Found only in the forests of Ashenvale, its darkened scales allow it to hide among the trees and groves undetected.\"\nTrading Post"}
MultiLanguageSpellData['en'][1305207] = {name = "Crested Verdant Leafmimic", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"Found primarily in areas with dense vegetation, this leafmimic is rarely spotted due to the natural hues of its scales, allowing it to blend in with its surroundings.\"\nTrading Post"}
MultiLanguageSpellData['en'][1305209] = {name = "Crested Violet Leafmimic", additional_info = "1.5 sec cast\n[q]Summons and dismisses this mount.\n[q]\"The violet leafmimic can be found in most dense jungles -- but only if your eyesight is keen. The patterns on their scales allow them to blend in with the vibrant foliage and shadows.\"\nTrading Post"}
